CREATE PROCEDURE telemetry_retire_shards(IN cutoff BIGINT)
SQL SECURITY DEFINER
BEGIN
 DECLARE clock_at BIGINT;
 DECLARE since_at BIGINT;
 DECLARE guard_key VARBINARY(128);
 DECLARE migration_state VARBINARY(16);
 DECLARE candidate VARBINARY(64);
 DECLARE statement_open BOOLEAN DEFAULT FALSE;
 DECLARE EXIT HANDLER FOR SQLEXCEPTION
 BEGIN
  IF statement_open THEN DEALLOCATE PREPARE telemetry_finalization; END IF;
  SET @telemetry_finalization_sql=NULL;
  RESIGNAL;
 END;
 SET clock_at=TIMESTAMPDIFF(MICROSECOND,'2000-01-01',UTC_TIMESTAMP(6));
 IF cutoff IS NULL OR cutoff>clock_at-1209600000000+300000000 THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='telemetry retention cutoff outside permitted window';
 END IF;
 SELECT lock_key INTO guard_key FROM business_locks WHERE lock_key='telemetry-shard-catalog' LOCK IN SHARE MODE;
 SELECT state INTO migration_state FROM telemetry_legacy_migration WHERE singleton=1 LOCK IN SHARE MODE;
 IF guard_key IS NULL OR migration_state IS NULL OR migration_state<>'complete' THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='telemetry history migration is incomplete';
 END IF;
 SET guard_key=NULL;
 SELECT key_name INTO guard_key FROM exact_key_guards WHERE key_name='telemetry_rollups_5m' FOR UPDATE;
 IF guard_key IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='missing exact-key guard'; END IF;
 SET guard_key=NULL;
 SELECT key_name INTO guard_key FROM exact_key_guards WHERE key_name='telemetry_rollups_1h' FOR UPDATE;
 IF guard_key IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='missing exact-key guard'; END IF;
 SELECT table_name INTO candidate FROM telemetry_sample_shards WHERE state='active' AND end_at<=LEAST(cutoff,clock_at-1209600000000) ORDER BY start_at LIMIT 1 FOR UPDATE;
 IF candidate IS NOT NULL THEN
  IF CONVERT(candidate USING ascii) NOT REGEXP '^telemetry_samples_(m_[0-9]{6}|x_[pn][0-9]{7})$' THEN
   SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='invalid telemetry shard name';
  END IF;
 SET since_at=FLOOR((clock_at-7776000000000)/300000000)*300000000;
 SET @telemetry_finalization_sql=CONCAT('UPDATE telemetry_rollups_5m r JOIN (SELECT node_id,metric,CASE WHEN sampled_at IN (-9223372036854775808,9223372036854775807) THEN sampled_at ELSE FLOOR(CAST(sampled_at AS DECIMAL(20,0))/300000000)*300000000 END AS bucket_at,COUNT(*) AS sample_count,MIN(value) AS min_value,MAX(value) AS max_value,AVG(value) AS avg_value FROM (SELECT node_id,metric,sampled_at,value FROM `',candidate,'` WHERE sampled_at>=',since_at,') AS samples GROUP BY node_id,metric,bucket_at) a ON r.node_id=a.node_id AND BINARY r.metric=BINARY a.metric AND r.bucket_at=a.bucket_at SET r.sample_count=a.sample_count,r.min_value=a.min_value,r.max_value=a.max_value,r.avg_value=a.avg_value');
 PREPARE telemetry_finalization FROM @telemetry_finalization_sql;
 SET statement_open=TRUE;
 EXECUTE telemetry_finalization;
 DEALLOCATE PREPARE telemetry_finalization;
 SET statement_open=FALSE;
 SET @telemetry_finalization_sql=CONCAT('INSERT INTO telemetry_rollups_5m(node_id,metric,bucket_at,sample_count,min_value,max_value,avg_value) SELECT a.node_id,a.metric,a.bucket_at,a.sample_count,a.min_value,a.max_value,a.avg_value FROM (SELECT node_id,metric,CASE WHEN sampled_at IN (-9223372036854775808,9223372036854775807) THEN sampled_at ELSE FLOOR(CAST(sampled_at AS DECIMAL(20,0))/300000000)*300000000 END AS bucket_at,COUNT(*) AS sample_count,MIN(value) AS min_value,MAX(value) AS max_value,AVG(value) AS avg_value FROM (SELECT node_id,metric,sampled_at,value FROM `',candidate,'` WHERE sampled_at>=',since_at,') AS samples GROUP BY node_id,metric,bucket_at) a LEFT JOIN telemetry_rollups_5m r ON r.node_id=a.node_id AND BINARY r.metric=BINARY a.metric AND r.bucket_at=a.bucket_at WHERE r.exact_row_id IS NULL');
 PREPARE telemetry_finalization FROM @telemetry_finalization_sql;
 SET statement_open=TRUE;
 EXECUTE telemetry_finalization;
 DEALLOCATE PREPARE telemetry_finalization;
 SET statement_open=FALSE;
 SET since_at=FLOOR(TIMESTAMPDIFF(MICROSECOND,'2000-01-01',DATE_SUB(UTC_TIMESTAMP(6),INTERVAL 13 MONTH))/3600000000)*3600000000;
 SET @telemetry_finalization_sql=CONCAT('UPDATE telemetry_rollups_1h r JOIN (SELECT node_id,metric,CASE WHEN sampled_at IN (-9223372036854775808,9223372036854775807) THEN sampled_at ELSE FLOOR(CAST(sampled_at AS DECIMAL(20,0))/3600000000)*3600000000 END AS bucket_at,COUNT(*) AS sample_count,MIN(value) AS min_value,MAX(value) AS max_value,AVG(value) AS avg_value FROM (SELECT node_id,metric,sampled_at,value FROM `',candidate,'` WHERE sampled_at>=',since_at,') AS samples GROUP BY node_id,metric,bucket_at) a ON r.node_id=a.node_id AND BINARY r.metric=BINARY a.metric AND r.bucket_at=a.bucket_at SET r.sample_count=a.sample_count,r.min_value=a.min_value,r.max_value=a.max_value,r.avg_value=a.avg_value');
 PREPARE telemetry_finalization FROM @telemetry_finalization_sql;
 SET statement_open=TRUE;
 EXECUTE telemetry_finalization;
 DEALLOCATE PREPARE telemetry_finalization;
 SET statement_open=FALSE;
 SET @telemetry_finalization_sql=CONCAT('INSERT INTO telemetry_rollups_1h(node_id,metric,bucket_at,sample_count,min_value,max_value,avg_value) SELECT a.node_id,a.metric,a.bucket_at,a.sample_count,a.min_value,a.max_value,a.avg_value FROM (SELECT node_id,metric,CASE WHEN sampled_at IN (-9223372036854775808,9223372036854775807) THEN sampled_at ELSE FLOOR(CAST(sampled_at AS DECIMAL(20,0))/3600000000)*3600000000 END AS bucket_at,COUNT(*) AS sample_count,MIN(value) AS min_value,MAX(value) AS max_value,AVG(value) AS avg_value FROM (SELECT node_id,metric,sampled_at,value FROM `',candidate,'` WHERE sampled_at>=',since_at,') AS samples GROUP BY node_id,metric,bucket_at) a LEFT JOIN telemetry_rollups_1h r ON r.node_id=a.node_id AND BINARY r.metric=BINARY a.metric AND r.bucket_at=a.bucket_at WHERE r.exact_row_id IS NULL');
 PREPARE telemetry_finalization FROM @telemetry_finalization_sql;
 SET statement_open=TRUE;
 EXECUTE telemetry_finalization;
 DEALLOCATE PREPARE telemetry_finalization;
 SET statement_open=FALSE;
 UPDATE telemetry_sample_shards SET state='retired' WHERE table_name=candidate AND state='active';
 END IF;
 SET @telemetry_finalization_sql=NULL;
END

